require_role(['admin','officer']);require __DIR__.'/staff_ui.php';
if($page==='areas'){
 require_role('admin');layout_start('Areas & officer workload','Set service coverage and compare open work before assigning reports.');
 $areas=service_areas();$officers=officer_workloads();
?><div class="two-col"><section class="panel"><h2>Create a service area</h2><p class="small muted">Use your own town, ward or service-region names. Area selection is manual and is not inferred from the map pin.</p><form method="post"><?php csrf();?><input type="hidden" name="action" value="create_area"><label>Area name<input name="area_name" minlength="2" maxlength="100" required placeholder="e.g. Maharagama"></label><button class="button">Add area</button></form><div class="category-pills section-space"><?php foreach($areas as $a):?><span><?=e($a['name'])?></span><?php endforeach;?></div></section><section class="panel"><h2>How assignments are suggested</h2><p>Officers who cover the selected area are listed first. Within that group, officers with fewer open reports appear first.</p><p class="small muted">An officer with no selected coverage areas is unrestricted and may receive work from any area. Open workload includes reports awaiting approval. Changing coverage cannot exclude existing open assignments.</p></section></div>
<section class="panel section-space"><h2>Active officer coverage</h2><?php if(!$officers):?><p>Create an officer under People & categories first.</p><?php endif;?><div class="coverage-grid"><?php foreach($officers as $o):$selected=array_column(q('SELECT area_id FROM officer_areas WHERE officer_id=?',[$o['id']])->fetchAll(),'area_id');?><article class="coverage-card"><h3><?=e($o['name'])?></h3><p class="small"><strong><?=$o['workload']?> open reports</strong> · <?=e($o['coverage']?:'Unrestricted coverage')?></p><form method="post"><?php csrf();?><input type="hidden" name="action" value="officer_coverage"><input type="hidden" name="officer_id" value="<?=$o['id']?>"><label>Coverage areas<select multiple size="5" name="area_ids[]"><?php foreach($areas as $a):?><option value="<?=$a['id']?>" <?=in_array($a['id'],$selected)?'selected':''?>><?=e($a['name'])?></option><?php endforeach;?></select></label><p class="small muted">Use Ctrl/Cmd to select several. No selection means unrestricted.</p><button class="button secondary">Save coverage</button></form></article><?php endforeach;?></div></section><?php echo '</div>';layout_end();return;
}
if($page==='dashboard' && user()['role']==='admin'){require __DIR__.'/admin_overview.php';return;}
if($page==='dashboard' && user()['role']==='officer'){require __DIR__.'/officer_overview.php';return;}
try{$filter=staff_filter();}catch(RuntimeException $ex){http_response_code(422);layout_start('Check your filters');echo '<div class="alert error">'.e($ex->getMessage()).'</div><a class="button secondary" href="index.php?page='.($page==='reports'?'reports':'dashboard').'">Reset filters</a>';layout_end();return;}
$sql=$filter['sql'];$params=$filter['params'];
$stats=q("SELECT COUNT(*) total,COALESCE(SUM(i.status NOT IN ('Resolved','Rejected','Duplicate')),0) open_count,COALESCE(SUM(i.status='Awaiting Approval'),0) approval,COALESCE(SUM(i.status='Resolved'),0) resolved,COALESCE(SUM(i.officer_id IS NULL AND i.status NOT IN ('Resolved','Rejected','Duplicate')),0) unassigned,COALESCE(SUM(i.priority='High' AND i.status NOT IN ('Resolved','Rejected','Duplicate')),0) high_count,COALESCE(SUM(".staff_overdue_sql()."),0) overdue,AVG(CASE WHEN i.status='Resolved' THEN TIMESTAMPDIFF(SECOND,i.created_at,i.resolved_at)/86400 END) avg_days FROM issues i".$sql,$params)->fetch();
$title=$page==='reports'?'Reports & export':(user()['role']==='admin'?'Community operations':'My work overview');
layout_start($title,user()['role']==='admin'?'Review reports, balance workloads and approve completed work.':'Analyse your assignments by date, team and stage. Export the current selection.');
if($page==='dashboard'):?><nav class="report-tabs" aria-label="Work queues"><?php foreach(['all'=>'All work','unassigned'=>'Unassigned','overdue'=>'Overdue','high'=>'High priority','approval'=>'Province final approval'] as $key=>$label):if($key==='unassigned'&&user()['role']!=='admin')continue;$query=$_GET;$query['page']='dashboard';$query['view']=$key;unset($query['p'],$query['status'],$query['priority']);?><a class="report-tab <?=$filter['values']['view']===$key?'selected':''?>" href="?<?=e(http_build_query($query))?>"><?=$label?></a><?php endforeach;?></nav><?php endif;
if(user()['role']==='officer'){echo '<div class="officer-workspace"><details class="officer-analytics-filter"'.(count(array_diff(array_keys($_GET),['page','p']))?' open':'').'><summary>Filters & date range <span>Area, category, team and work stage</span></summary>';staff_filters($filter,'reports');echo '</details>';}else {echo '<div class="admin-workspace">';admin_report_filters($filter);}
workspace_date_shortcuts();workspace_filter_chips($filter['values']);
?><section class="staff-stat-grid"><?php foreach([['Reports',$stats['total']],['Open',$stats['open_count']],['Province final approval',$stats['approval']],['Overdue',$stats['overdue']],['High priority',$stats['high_count']],['Resolved',$stats['resolved']]] as $stat):?><div class="stat"><span class="small muted"><?=$stat[0]?></span><strong><?=$stat[1]?></strong></div><?php endforeach;?></section>
<div class="section-heading"><h2><?=$page==='reports'?'Matching reports':'Work queue'?></h2><?php $query=$_GET;$query['page']='staff_export';unset($query['p']);?><a class="button secondary" href="?<?=e(http_build_query($query))?>">Export filtered CSV ↓</a></div>
<?php $limit=20;$max=max(1,(int)ceil($stats['total']/$limit));$pn=min($max,max(1,(int)($_GET['p']??1)));$rows=q(issue_query().$sql.' ORDER BY '.$filter['order'].' LIMIT '.$limit.' OFFSET '.(($pn-1)*$limit),$params)->fetchAll();?><section class="panel no-pad"><?php staff_table($rows);?></section>
<?php if($max>1):?><nav class="pagination"><span>Page <?=$pn?> of <?=$max?></span><?php foreach([[-1,'← Previous'],[1,'Next →']] as $step):$next=$pn+$step[0];if($next<1||$next>$max)continue;$query=$_GET;$query['p']=$next;?><a class="button secondary" href="?<?=e(http_build_query($query))?>"><?=$step[1]?></a><?php endforeach;?></nav><?php endif;?>
<div class="section-space"><section class="panel"><h2>Category summary</h2><?php $summary=q('SELECT c.name,COUNT(*) n FROM issues i JOIN categories c ON c.id=i.category_id'.$sql.' GROUP BY c.id,c.name ORDER BY n DESC',$params)->fetchAll();if(!$summary)echo '<p class="small muted">No reports in this selection.</p>';foreach($summary as $item):?><div class="row between summary-line"><span><?=e($item['name'])?></span><strong><?=$item['n']?></strong></div><?php endforeach;?><p class="small muted section-space">Average resolution time: <strong><?=$stats['avg_days']!==null?round($stats['avg_days'],2).' days':'No resolved reports in this selection'?></strong>. All summaries use the selected filters.</p></section>
</div>
<?php echo '</div>';layout_end();
